namespace sv_715a563034934e09b3c261606072c6c6.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Williams"
    ];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Patel"] = ["9:30 AM", "10:00 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Williams"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        var slots = DoctorSlots.GetValueOrDefault(doctor, []);
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates the patient and appointment details against server-side rules.
    /// Returns a dictionary of field name → error message for any validation failures.
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        if (timeSlot == "10:00 AM")
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_715a563034934e09b3c261606072c6c6.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book an Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmitAsync">
    <DataAnnotationsValidator />

    @* ───── STEP 1: Patient Information ───── *@
    <fieldset>
        <legend>Step 1 — Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.TryGetValue("Email", out var emailErr))
            {
                <div class="validation-message">@emailErr</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2Async">
                Next
            </button>
        }
    </fieldset>

    @* ───── STEP 2: Appointment Details ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2 — Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorOrDateChangedAsync">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.TryGetValue("Doctor", out var docErr))
                {
                    <div class="validation-message">@docErr</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control"
                           @bind-Value="Model.Date"
                           @bind-Value:after="OnDoctorOrDateChangedAsync" />
                <ValidationMessage For="() => Model.Date" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.TryGetValue("TimeSlot", out var slotErr))
                {
                    <div class="validation-message">@slotErr</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.Reason" />
                <ValidationMessage For="() => Model.Reason" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-primary" @onclick="CheckAvailabilityAsync">
                    Check Availability
                </button>
                @if (availabilityConfirmed)
                {
                    <button type="submit" class="btn btn-success">
                        Confirm Appointment
                    </button>
                }
            </div>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool showStep2;
    private bool availabilityConfirmed;
    private bool submitted;
    private List<string> doctors = [];
    private List<string> timeSlots = [];
    private Dictionary<string, string> serverErrors = new();
    private EditContext? editContext;

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
    }

    private async Task ProceedToStep2Async()
    {
        editContext = new EditContext(Model);
        var step1Valid =
            !string.IsNullOrWhiteSpace(Model.PatientName) &&
            !string.IsNullOrWhiteSpace(Model.Email) &&
            IsValidEmail(Model.Email) &&
            !string.IsNullOrWhiteSpace(Model.Phone) &&
            !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (!step1Valid)
        {
            // Trigger DataAnnotations so messages appear
            editContext.Validate();
            return;
        }

        doctors = await AppointmentSvc.GetDoctorsAsync();
        showStep2 = true;
        availabilityConfirmed = false;
        serverErrors.Clear();
    }

    private static bool IsValidEmail(string email)
    {
        try { var addr = new System.Net.Mail.MailAddress(email); return addr.Address == email; }
        catch { return false; }
    }

    private async Task OnDoctorOrDateChangedAsync()
    {
        availabilityConfirmed = false;
        serverErrors.Clear();
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.Date.HasValue)
        {
            timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                Model.Doctor, DateOnly.FromDateTime(Model.Date.Value));
        }
        else
        {
            timeSlots = [];
        }
    }

    private async Task CheckAvailabilityAsync()
    {
        serverErrors.Clear();
        availabilityConfirmed = false;

        editContext = new EditContext(Model);
        if (!editContext.Validate())
            return;

        var errors = await AppointmentSvc.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor ?? string.Empty,
            Model.TimeSlot ?? string.Empty);

        if (errors.Count > 0)
        {
            serverErrors = errors;
            return;
        }

        availabilityConfirmed = true;
    }

    private Task HandleSubmitAsync()
    {
        if (availabilityConfirmed)
        {
            submitted = true;
        }
        return Task.CompletedTask;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
        serverErrors.Clear();
    }

    public class AppointmentModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required.")]
        public string PatientName { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required.")]
        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format.")]
        public string Email { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required.")]
        public string Phone { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required.")]
        public string InsuranceProvider { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Doctor is required.")]
        public string? Doctor { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required.")]
        [FutureDate(ErrorMessage = "Date must be in the future.")]
        public DateTime? Date { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Time slot is required.")]
        public string? TimeSlot { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required.")]
        [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
        public string? Reason { get; set; }
    }

    private class FutureDateAttribute : System.ComponentModel.DataAnnotations.ValidationAttribute
    {
        protected override System.ComponentModel.DataAnnotations.ValidationResult? IsValid(
            object? value,
            System.ComponentModel.DataAnnotations.ValidationContext validationContext)
        {
            if (value is DateTime dt && dt.Date <= DateTime.Today)
                return new System.ComponentModel.DataAnnotations.ValidationResult(ErrorMessage);
            return System.ComponentModel.DataAnnotations.ValidationResult.Success;
        }
    }
}

